let src = {};
try { src = $('Pick Subpages').item.json || {}; } catch (e) { src = {}; }
const o = ($json.output) ? $json.output : $json;

// Get full body text from Extract Content step
let fullContent = '';
try { fullContent = $('Extract Content').item.json.body_text || ''; } catch(e) {}

// Use full body_text as content (up to 20000 chars), GPT summary as summary
const content = String(fullContent || o.summary || '').slice(0, 20000);

return { json: {
  source_id: src.source_id || '',
  source_name: src.source_name || '',
  source_type: 'html',
  title: o.title || src.anchor_text || '',
  url: src.sub_url || '',
  content: content,
  summary: o.summary || '',
  published_at: (o.published_at && String(o.published_at).trim()) ? o.published_at : null,
  fetched_at: new Date().toISOString()
} };

function norm(s){ return String(s||'').toLowerCase().normalize('NFKD').replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim(); }
function normUrl(u){ return String(u||'').toLowerCase().replace(/^https?:\/\//,'').replace(/[?#].*$/,'').replace(/\/$/,''); }
function hash(str){ let h=5381; for(let i=0;i<str.length;i++){ h=((h<<5)+h)+str.charCodeAt(i); h=h&0xffff; } return (h>>>0).toString(16); }
const j = $json;
const tn = norm(j.title);
const ch = hash(tn + '|' + normUrl(j.url));
// Keep existing category from HTML GPT path; others will be overwritten by LLM Classify
return { json: Object.assign({}, j, {
  title_normalized: tn,
  content_hash: ch,
  category: j.category || 'General',
  severity: j.severity || 'INFO',
  tags: j.tags || []
}) };

const existing = $input.all().map(i => i.json).filter(e => e && e.content_hash);
const existingHashes = new Set(existing.map(e => e.content_hash));
const existingUrls = new Set(existing.map(e => String(e.url || '').toLowerCase()));
const candidates = $('Add Hash').all().map(i => i.json);
const seen = new Set();
const out = [];
candidates.forEach(c => {
  if (existingHashes.has(c.content_hash)) return;
  if (existingUrls.has(String(c.url || '').toLowerCase())) return;
  if (seen.has(c.content_hash)) return;
  seen.add(c.content_hash);
  out.push({ json: c });
});
return out;

function cos(a,b){ if(!a||!b||!a.length||a.length!==b.length) return 0; let d=0,na=0,nb=0; for(let i=0;i<a.length;i++){ d+=a[i]*b[i]; na+=a[i]*a[i]; nb+=b[i]*b[i]; } if(!na||!nb) return 0; return d/(Math.sqrt(na)*Math.sqrt(nb)); }
const cands = $('Hash Dedup').all().map(i => i.json);
const resp = $input.all();
const items = cands.map((c, i) => {
  const r = resp[i] && resp[i].json ? resp[i].json : {};
  const e = r.data && r.data[0] ? r.data[0].embedding : null;
  return Object.assign({}, c, { embedding: Array.isArray(e) ? e : null });
});
const existing = $('MongoDB Find Existing').all().map(i => i.json).filter(e => e && Array.isArray(e.embedding));
const TH = 0.9;
const kept = [];
items.forEach(it => {
  it.dedup_group_id = it.content_hash;
  if (!it.embedding) { kept.push(it); return; }
  let dup = false;
  for (const e of existing) { if (cos(it.embedding, e.embedding) >= TH) { dup = true; it.dedup_group_id = e.dedup_group_id || e.content_hash; break; } }
  if (dup) return;
  for (const k of kept) { if (Array.isArray(k.embedding) && cos(it.embedding, k.embedding) >= TH) { dup = true; it.dedup_group_id = k.dedup_group_id; break; } }
  if (dup) return;
  kept.push(it);
});
return kept.map(k => ({ json: k }));

// ================================================================
// ✏️  KATEGORİZASYON PROMPT'U — istediğin zaman buradan düzenle
// ================================================================

const CATEGORIES = [
  'Airworthiness Directive',  // FAA/EASA/CASA tarafından yayımlanan zorunlu direktif
  'Accident Report',          // Ölümlü kaza, hull loss, resmi kaza soruşturması
  'Incident Report',          // Yaralanmasız olay, near-miss, pist ihlali
  'Safety Alert',             // SAFO, InFO, acil güvenlik bildirimi
  'Safety Bulletin',          // Zorunlu olmayan güvenlik tavsiyesi
  'Regulatory Update',        // Yeni yönetmelik, kural değişikliği
  'Technical Notice',         // Bakım, servis bülteni (AD dışı)
  'Industry News',            // Genel havacılık haberi, finansal, operasyonel
  'General'                   // Hiçbirine uymayan
];

const SEVERITY_GUIDE = `
CRITICAL : Ölümlü kaza, hull loss, çok sayıda kayıp onaylandı
HIGH     : Airworthiness directive, serious incident, uçuşta motor yangını, acil tahliye
MEDIUM   : Potansiyel yaralanma riski olan olay, ihtiyati iniş, safety bulletin
LOW      : Tavsiye niteliğinde, yaralanmasız, bilgilendirme amaçlı
INFO     : Genel haber, sektör güncellemesi, güvenlikle doğrudan ilgisiz
`;

const AVAILABLE_TAGS = [
  // Üreticiler
  'Airbus','Boeing','Embraer','ATR','Bombardier','Cessna','Piper',
  // Uçak tipleri (sık)
  'A320','A330','A350','A380','B737','B737 MAX','B777','B787',
  // Sistem/arıza
  'Engine Failure','Landing Gear','Fire','Bird Strike','Runway Excursion',
  'TCAS/ACAS','Weather','ATC','Fuel','Structural','Electrical','Hydraulics',
  'Pressurization','Windshield','Flaps/Slats',
  // Faz
  'Go-Around','CFIT','Loss of Control','Tail Strike','Hard Landing',
  // Kurum
  'FAA','EASA','ICAO','NTSB','AAIB','BEA','ATSB','TSB','TAIC'
];

const SYSTEM_PROMPT = \`Sen uzman bir havacılık güvenliği analistisi ve içerik sınıflandırıcısısın.

Sana bir havacılık haberi/güvenlik öğesinin başlığı ve özeti verilecek.
Aşağıdaki kurallara göre JSON formatında sınıflandırma yapacaksın.

KATEGORİLER (tam olarak birini seç):
\${CATEGORIES.map((c,i) => \`\${i+1}. \${c}\`).join('\n')}

CİDDİYET (tam olarak birini seç):
\${SEVERITY_GUIDE}

ETİKETLER: Listeden 1-5 etiket seç. Listede yoksa spesifik uçak tipini ekleyebilirsin (ör. "A320neo").

SADECE aşağıdaki JSON formatını döndür (markdown yok, açıklama yok):
{
  "category": "...",
  "severity": "...",
  "tags": ["...", "..."],
  "reasoning": "tek cümle Türkçe açıklama"
}\`;

const j = $json;
const userContent = \`Başlık: \${j.title || '(başlık yok)'}
Özet: \${(j.summary || j.content || '').slice(0, 1000)}
Kaynak: \${j.source_name || 'Bilinmiyor'}
Mevcut kategori: \${j.category || 'belirlenmedi'}\`;

return { json: { ...j, _prompt_system: SYSTEM_PROMPT, _prompt_user: userContent } };

let orig = {};
try { orig = $('Build Prompt').item.json || {}; } catch(e) { orig = {}; }

const resp = $json;
let cls = { category: orig.category || 'General', severity: 'INFO', tags: orig.tags || [], reasoning: '' };

try {
  const raw = resp.choices && resp.choices[0] ? resp.choices[0].message.content : '{}';
  const parsed = JSON.parse(raw);
  if (parsed.category) cls.category = parsed.category;
  if (parsed.severity) cls.severity = parsed.severity;
  if (Array.isArray(parsed.tags) && parsed.tags.length) cls.tags = parsed.tags;
  if (parsed.reasoning) cls.reasoning = parsed.reasoning;
} catch(e) {
  // GPT parse hatası — mevcut değerleri koru
}

// _prompt_ alanlarını temizle
const { _prompt_system, _prompt_user, ...cleanOrig } = orig;

return { json: {
  ...cleanOrig,
  category: cls.category,
  severity: cls.severity,
  tags: cls.tags,
  classification_reasoning: cls.reasoning
} };
